/* Runtime support for C generated by src/lifter/a32lift.py (ARM A32 guest -> C).
 * Guest memory: a 4 GB reservation; guest address a (u32) is host address MB + a, so any 32-bit value is inside it. */
#ifndef A32RT_H
#define A32RT_H
#include <stdint.h>
#include <string.h>

typedef struct {
    uint32_t r[16];
    uint32_t N, Z, C, V;
    uint32_t exon, exa;      /* exclusive monitor (LDREX / LDAEX): armed, address */
    uint64_t exv;            /* value seen by the exclusive load (a store-exclusive also compares it, as QEMU does) */
} Ctx;

extern uint8_t *MB;    /* guest memory base */

/* provided by the runtime (or by the test harness) */
void call_indirect(Ctx *c, uint32_t addr);        /* BLX / BX to a register: the lifted function at addr */
void imp_call(Ctx *c, int idx);                   /* call through PLT stub idx (R_ARM_JUMP_SLOT index) */
void guest_unimpl(Ctx *c, uint32_t pc, uint32_t insn);

static inline uint32_t rd32(uint32_t a) { uint32_t v; memcpy(&v, MB + a, 4); return v; }
static inline uint32_t rd16(uint32_t a) { uint16_t v; memcpy(&v, MB + a, 2); return v; }
static inline uint32_t rd8(uint32_t a) { return MB[a]; }
static inline void wr32(uint32_t a, uint32_t v) { memcpy(MB + a, &v, 4); }
static inline void wr16(uint32_t a, uint32_t v) { uint16_t h = (uint16_t)v; memcpy(MB + a, &h, 2); }
static inline void wr8(uint32_t a, uint32_t v) { MB[a] = (uint8_t)v; }

/* condition codes (ARM ARM A8.3) */
#define C_EQ (c->Z)
#define C_NE (!c->Z)
#define C_CS (c->C)
#define C_CC (!c->C)
#define C_MI (c->N)
#define C_PL (!c->N)
#define C_VS (c->V)
#define C_VC (!c->V)
#define C_HI (c->C && !c->Z)
#define C_LS (!c->C || c->Z)
#define C_GE (c->N == c->V)
#define C_LT (c->N != c->V)
#define C_GT (!c->Z && c->N == c->V)
#define C_LE (c->Z || c->N != c->V)

/* shift by an immediate (DecodeImmShift): type 0 LSL, 1 LSR, 2 ASR, 3 ROR; LSR/ASR #0 mean #32, ROR #0 means RRX.
 * *co receives the shifter carry-out (C unchanged for LSL #0). */
static inline uint32_t sh_imm(const Ctx *c, uint32_t v, int type, unsigned n, uint32_t *co) {
    switch (type) {
    case 0: if (n == 0) { *co = c->C; return v; } *co = (v >> (32 - n)) & 1; return v << n;
    case 1: if (n == 0) { *co = v >> 31; return 0; } *co = (v >> (n - 1)) & 1; return v >> n;
    case 2: if (n == 0) { *co = v >> 31; return (uint32_t)((int32_t)v >> 31); } *co = (v >> (n - 1)) & 1; return (uint32_t)((int32_t)v >> n);
    default:
        if (n == 0) { *co = v & 1; return (c->C << 31) | (v >> 1); }
        *co = (v >> (n - 1)) & 1; return (v >> n) | (v << (32 - n));
    }
}
/* shift by a register (bottom byte of Rs) */
static inline uint32_t sh_reg(const Ctx *c, uint32_t v, int type, uint32_t rs, uint32_t *co) {
    unsigned n = rs & 0xff;
    if (n == 0) { *co = c->C; return v; }
    switch (type) {
    case 0: if (n < 32) { *co = (v >> (32 - n)) & 1; return v << n; } *co = n == 32 ? v & 1 : 0; return 0;
    case 1: if (n < 32) { *co = (v >> (n - 1)) & 1; return v >> n; } *co = n == 32 ? v >> 31 : 0; return 0;
    case 2: if (n < 32) { *co = (v >> (n - 1)) & 1; return (uint32_t)((int32_t)v >> n); } *co = v >> 31; return (uint32_t)((int32_t)v >> 31);
    default: { unsigned m = n & 31; if (m == 0) { *co = v >> 31; return v; } *co = (v >> (m - 1)) & 1; return (v >> m) | (v << (32 - m)); }
    }
}
/* AddWithCarry; sets N Z C V when s */
static inline uint32_t awc(Ctx *c, uint32_t a, uint32_t b, uint32_t cin, int s) {
    uint64_t u = (uint64_t)a + b + cin;
    uint32_t r = (uint32_t)u;
    if (s) {
        c->N = r >> 31; c->Z = r == 0; c->C = (uint32_t)(u >> 32);
        c->V = (((a ^ r) & (b ^ r)) >> 31) & 1;
    }
    return r;
}
static inline uint32_t nz(Ctx *c, uint32_t r, uint32_t co) { c->N = r >> 31; c->Z = r == 0; c->C = co; return r; }
static inline uint32_t clz32(uint32_t v) { uint32_t n = 0; if (!v) return 32; while (!(v & 0x80000000u)) { v <<= 1; n++; } return n; }

#endif
